```java
int day = 1;
String type;
switch (day) {
    case 1: type = "Weekend"; // no break!
    case 2: type = "Weekday"; // falls through and overwrites
    default: type = "Invalid";
}
System.out.println(type); // "Invalid" — not what we wanted
```

```java
int day = 1;
String type = switch (day) {
    case 1, 7 -> "Weekend";
    case 2, 3, 4, 5, 6 -> "Weekday";
    default -> "Invalid";
};
System.out.println(type); // "Weekend"
```

